const items = $input.all();

function normDoi(doi) {
  let s = String(doi ?? '').trim().toLowerCase();
  // remove doi prefix & url forms
  s = s.replace(/^doi:\s*/i, '');
  s = s.replace(/^https?:\/\/(dx\.)?doi\.org\//i, '');
  return s;
}

function normText(t) {
  return String(t ?? '')
    .trim()
    .toLowerCase()
    .replace(/\s+/g, ' ');
}

for (const it of items) {
  const title = normText(it.json.title);
  const year  = String(it.json.year || '').trim();
  const doi   = normDoi(it.json.doi);

  it.json.key = doi
    ? `doi:${doi}`
    : `ty:${title}|${year || 'na'}`;
}

return items;

const seen = new Set();
const out = [];

for (const it of $input.all()) {
  const k = it.json.key;
  if (!seen.has(k)) {
    seen.add(k);
    out.push(it);
  }
}

return out;

const items = $input.all();

function canonKey(v) {
  let s = String(v ?? '').trim().toLowerCase();

  // normalize DOI formats
  // examples handled:
  // - doi:10.xxxx/yyy
  // - https://doi.org/10.xxxx/yyy
  // - http://dx.doi.org/10.xxxx/yyy
  s = s.replace(/^doi:\s*/i, '');
  s = s.replace(/^https?:\/\/(dx\.)?doi\.org\//i, '');

  // normalize whitespace
  s = s.replace(/\s+/g, ' ').trim();

  return s;
}

// แยกของเก่าจากชีต vs ของใหม่จากการค้นหา
const oldItems = items.filter(i => i.json.from_sheet === true);
const newItems = items.filter(i => i.json.from_sheet !== true);

// สร้าง set ของ key ที่มีอยู่แล้ว (จากชีต)
const existing = new Set(
  oldItems.map(i => canonKey(i.json.key)).filter(Boolean)
);

// คืนเฉพาะรายการใหม่ที่ยังไม่มี key ในชีต
return newItems.filter(i => {
  const k = canonKey(i.json.key);
  return k && !existing.has(k);
});

// ======================================================
// Detect Publisher
// รองรับ OpenAlex, Crossref และ Semantic Scholar
// ตรวจจาก Publisher Raw, Journal, URL และ DOI Prefix
// Mode: Run Once for Each Item
// ======================================================

const data = $json;

// ------------------------------------------------------
// ฟังก์ชันเลือกค่าตัวแรกที่ไม่ว่าง
// ------------------------------------------------------
function firstNonEmpty(...values) {
  for (const value of values) {
    if (value === null || value === undefined) {
      continue;
    }

    const text = String(value).trim();

    if (text !== "") {
      return text;
    }
  }

  return "";
}

// ------------------------------------------------------
// ฟังก์ชันแปลงข้อมูล URL หรือ Array ให้เป็นข้อความ
// ------------------------------------------------------
function valueToText(value) {
  if (value === null || value === undefined) {
    return "";
  }

  if (Array.isArray(value)) {
    return value
      .map(item => valueToText(item))
      .filter(Boolean)
      .join(" ");
  }

  if (typeof value === "object") {
    return firstNonEmpty(
      value.URL,
      value.url,
      value.href,
      value.display_name,
      value.name
    );
  }

  return String(value).trim();
}

// ------------------------------------------------------
// 1. Publisher Raw
// ------------------------------------------------------
const publisherRaw = firstNonEmpty(
  data.publisher_raw,
  data.publisherRaw,
  data.host_organization_name,
  data.primary_location?.source?.host_organization_name,
  data.primary_location?.source?.display_name,
  data.publisher
);

// ------------------------------------------------------
// 2. Journal / Venue
// ------------------------------------------------------
const journal = firstNonEmpty(
  data.journal,
  data.venue,
  data.journal?.name,
  data.container_title,
  data["container-title"]?.[0],
  data.primary_location?.source?.display_name
);

// ------------------------------------------------------
// 3. DOI
// รองรับชื่อฟิลด์จากทุกแหล่งข้อมูล
// ------------------------------------------------------
const doiRaw = firstNonEmpty(
  data.doi,
  data.DOI,
  data.externalIds?.DOI,
  data.externalIds?.doi,
  data.ids?.doi,
  data.primary_location?.id
);

const doi = String(doiRaw || "")
  .replace(/^https?:\/\/(?:dx\.)?doi\.org\//i, "")
  .replace(/^doi:\s*/i, "")
  .trim()
  .toLowerCase();

// ------------------------------------------------------
// 4. URL
// ------------------------------------------------------
const linkText = [
  valueToText(data.link),
  valueToText(data.url),
  valueToText(data.URL),
  valueToText(data.openAccessPdf?.url),
  valueToText(data.primary_location?.landing_page_url),
  valueToText(data.primary_location?.pdf_url),
  valueToText(data.resource?.primary?.URL),
  valueToText(data.links)
]
  .filter(Boolean)
  .join(" ");

// ------------------------------------------------------
// รวมข้อมูลทั้งหมดสำหรับตรวจสอบ
// ------------------------------------------------------
const sourceText = [
  publisherRaw,
  journal,
  linkText,
  doi
]
  .filter(Boolean)
  .join(" ")
  .toLowerCase();

// ------------------------------------------------------
// กฎตรวจสอบ Publisher
// เรียงจากชื่อที่จำเพาะไปยังชื่อทั่วไป
// ------------------------------------------------------
const publisherRules = [
  {
    publisher: "Elsevier",
    patterns: [
      /elsevier/,
      /elsevier\s+bv/,
      /sciencedirect\.com/,
      /ssrn\.com/,
      /10\.1016\//,
      /10\.2139\//
    ]
  },
  {
    publisher: "MDPI",
    patterns: [
      /\bmdpi\b/,
      /mdpi\s+ag/,
      /multidisciplinary digital publishing institute/,
      /mdpi\.com/,
      /10\.3390\//
    ]
  },
  {
    publisher: "IEEE",
    patterns: [
      /\bieee\b/,
      /institute of electrical and electronics engineers/,
      /ieeexplore\.ieee\.org/,
      /10\.1109\//
    ]
  },
  {
    publisher: "ACM",
    patterns: [
      /association for computing machinery/,
      /\bacm\b/,
      /dl\.acm\.org/,
      /10\.1145\//
    ]
  },
  {
    publisher: "PeerJ",
    patterns: [
      /\bpeerj\b/,
      /peerj,\s*inc/,
      /peerj\.com/,
      /10\.7717\//
    ]
  },
  {
    publisher: "Springer Nature",
    patterns: [
      /springer nature/,
      /springer science/,
      /springerlink/,
      /\bspringer\b/,
      /nature portfolio/,
      /nature publishing group/,
      /biomed central/,
      /\bbmc\b/,
      /link\.springer\.com/,
      /nature\.com/,
      /10\.1007\//,
      /10\.1038\//,
      /10\.1186\//
    ]
  },
  {
    publisher: "Wiley",
    patterns: [
      /\bwiley\b/,
      /john wiley/,
      /wiley-blackwell/,
      /onlinelibrary\.wiley\.com/,
      /10\.1002\//,
      /10\.1111\//
    ]
  },
  {
    publisher: "Taylor & Francis",
    patterns: [
      /taylor\s*(?:&|and)\s*francis/,
      /routledge/,
      /tandfonline\.com/,
      /10\.1080\//
    ]
  },
  {
    publisher: "SAGE",
    patterns: [
      /\bsage\b/,
      /sage publishing/,
      /sage publications/,
      /sagepub\.com/,
      /10\.1177\//
    ]
  },
  {
    publisher: "Frontiers",
    patterns: [
      /\bfrontiers\b/,
      /frontiersin\.org/,
      /10\.3389\//
    ]
  },
  {
    publisher: "Oxford University Press",
    patterns: [
      /oxford university press/,
      /academic\.oup\.com/,
      /10\.1093\//
    ]
  },
  {
    publisher: "Cambridge University Press",
    patterns: [
      /cambridge university press/,
      /cambridge\.org/,
      /10\.1017\//
    ]
  },
  {
    publisher: "PLOS",
    patterns: [
      /\bplos\b/,
      /public library of science/,
      /plos\.org/,
      /10\.1371\//
    ]
  },
  {
    publisher: "Emerald",
    patterns: [
      /\bemerald\b/,
      /emerald publishing/,
      /emerald\.com/,
      /10\.1108\//
    ]
  },
  {
    publisher: "IGI Global",
    patterns: [
      /igi global/,
      /igi-global\.com/,
      /10\.4018\//
    ]
  },
  {
    publisher: "Hindawi",
    patterns: [
      /\bhindawi\b/,
      /hindawi publishing corporation/,
      /hindawi\.com/,
      /10\.1155\//
    ]
  },
  {
    publisher: "IOP Publishing",
    patterns: [
      /iop publishing/,
      /iopscience\.iop\.org/,
      /10\.1088\//
    ]
  },
  {
    publisher: "American Chemical Society",
    patterns: [
      /american chemical society/,
      /acs publications/,
      /pubs\.acs\.org/,
      /10\.1021\//
    ]
  },
  {
    publisher: "Royal Society of Chemistry",
    patterns: [
      /royal society of chemistry/,
      /rsc publishing/,
      /pubs\.rsc\.org/,
      /10\.1039\//
    ]
  },
  {
    publisher: "American Physical Society",
    patterns: [
      /american physical society/,
      /aps physics/,
      /journals\.aps\.org/,
      /10\.1103\//
    ]
  },
  {
    publisher: "AIP Publishing",
    patterns: [
      /aip publishing/,
      /pubs\.aip\.org/,
      /10\.1063\//
    ]
  },
  {
    publisher: "BMJ",
    patterns: [
      /\bbmj\b/,
      /bmj publishing/,
      /bmj\.com/,
      /10\.1136\//
    ]
  },
  {
    publisher: "De Gruyter",
    patterns: [
      /de gruyter/,
      /degruyter\.com/,
      /10\.1515\//
    ]
  },
  {
    publisher: "JMIR Publications",
    patterns: [
      /jmir publications/,
      /jmir\.org/,
      /10\.2196\//
    ]
  },
  {
    publisher: "Preprints.org",
    patterns: [
      /preprints\.org/,
      /10\.20944\//
    ]
  },
  {
    publisher: "arXiv",
    patterns: [
      /\barxiv\b/,
      /arxiv\.org/,
      /10\.48550\/arxiv/
    ]
  }
];

// ------------------------------------------------------
// ตรวจสอบ Publisher ตามกฎ
// ------------------------------------------------------
let publisher = "";

for (const rule of publisherRules) {
  const matched = rule.patterns.some(pattern =>
    pattern.test(sourceText)
  );

  if (matched) {
    publisher = rule.publisher;
    break;
  }
}

// ------------------------------------------------------
// ถ้าตรวจไม่พบ ให้ใช้ Publisher Raw
// ------------------------------------------------------
if (!publisher) {
  publisher = publisherRaw || "Unknown";
}

// ------------------------------------------------------
// ส่งข้อมูลออก
// ------------------------------------------------------
return {
  json: {
    ...data,

    // เก็บค่าดิบจากฐานข้อมูลต้นทาง
    publisher_raw: publisherRaw,

    // ชื่อ Publisher ที่จัดมาตรฐานแล้ว
    publisher
  }
};

