const lineMessage = {

  type: 'flex',
  altText,
  contents: bubble

};

// ------------------------------------------------------
// 8. Output
// ------------------------------------------------------
return {

  json: {

    ...data,

    // สำหรับ LineMessageNode-Flex
    line_flex_alt_text: altText,
    line_flex_contents: bubble,
    line_flex_contents_json:
      JSON.stringify(bubble),

    // Alias รองรับ Node เดิม
    alt_text: altText,
    flex_content_json:
      JSON.stringify(bubble),

    // Message พร้อมส่ง
    line_message: lineMessage,
    message: lineMessage,
    messages: [lineMessage]

  }

};

parameters.jsonBody:
={{
  {
    to: $json.toId,
    messages: [
      {
        type: "flex",
        altText: $json.line_flex_alt_text,
        contents:
          typeof $json.line_flex_contents_json === "string"
            ? JSON.parse($json.line_flex_contents_json)
            : $json.line_flex_contents_json
